<template>
  <div class="full-width">
    <div
      v-if="formBuilderConfigModel[fieldName].displayLabelOnLeft"
      :style="'width:' + formBuilderConfigModel[fieldName].labelWidth + '%'"
      class="display-block"
    >
      <div
        :class="
          fieldName +
          ' ' +
          (showClearRuleButton(fieldName) ? ' label-area ' : ' full-width ')
        "
      >
        <span>{{
          getLabelForFormBuilder(
            formBuilderConfigModel[fieldName],
            '',
          )
        }}</span>
        <q-icon
          v-if="isFieldHidden()"
          name="visibility_off"
          size="xs"
          color="grey-6"
          class="q-ml-xs"
        >
          <q-tooltip>{{ $t('field_is_hidden') }}</q-tooltip>
        </q-icon>
        <ExtractionSourceBadge
          :extraction-method="formBuilderModel[fieldName]?.extraction_method"
        />
        <span v-if="false" class="text-red"> * </span>
      </div>
    </div>

    <div
      :style="
        'width:' + getInputFieldWidth(formBuilderConfigModel[fieldName]) + '%'
      "
      class="display-block"
    >
      <div
        class="col-sm-12 col-md-12 col-lg-12 display-flex"
        v-if="!formBuilderConfigModel[fieldName].displayLabelOnLeft"
      >
        <div
          class="ellipsify"
          :class="
            fieldName +
            ' ' +
            (showClearRuleButton(fieldName) ? 'label-area-fb' : 'full-width')
          "
        >
          <span> {{ getTranslations() }} </span>
          <q-icon
            v-if="isFieldHidden()"
            name="visibility_off"
            size="xs"
            color="grey-6"
            class="q-ml-xs"
          >
            <q-tooltip>{{ $t('field_is_hidden') }}</q-tooltip>
          </q-icon>
          <ExtractionSourceBadge
            :extraction-method="formBuilderModel[fieldName]?.extraction_method"
          />
          <span v-if="false" class="text-red"> * </span>

          <q-tooltip>{{
            getLabelForFormBuilder(
              formBuilderConfigModel[fieldName],
              '',
            )
          }}</q-tooltip>
        </div>

        <div class="width-35px" v-if="showClearRuleButton(fieldName)">
          <q-icon
            @click="deleteRuleConfirmation()"
            name="cancel"
            class="q-pb-xs float-right text-grey-7 cursor-pointer"
          >
            <q-tooltip>{{ $t('deleteRule') }}</q-tooltip>
          </q-icon>
          <!-- <img @click="deleteRuleConfirmation()"
          class="q-ml-xs cursor-pointer black_to_white" width="10"
          src="/images/trash-bin-default.svg"
        /> -->
        </div>
      </div>

      <div
        :id="fieldName"
        :child_type="formBuilderConfigModel[fieldName].is_textarea ? 'textarea' : 'input'"
        :data-test="'field-input-' + fieldName"
        class="col-sm-12 col-md-12 col-lg-12 autocomplete"
        :class="formBuilderConfigModel[fieldName].is_textarea ? ' ' : ' input-text-28px'"
        role="combobox"
        aria-autocomplete="list"
        aria-controls="suggestions"
        aria-expanded="false"
      >
        <q-input
          outlined
          dense
          :data-name="fieldName"
          :readonly="
            isReadOnly ||
            formBuilderConfigModel[fieldName].is_readonly ||
            (lookup_loading_fields.hasOwnProperty(fieldName) &&
              lookup_loading_fields[fieldName].lookup_loading)
          "
          :tabindex="formBuilderConfigModel[fieldName].tabIndex"
          :autogrow="formBuilderConfigModel[fieldName].is_textarea"
          :class="
            ' full-width ' +
            (fieldName + '_input ') +
            (formBuilderConfigModel[fieldName].is_textarea
              ? ' '
              : 'input-field ') +
            formBuilderConfigModel[fieldName].color +
            ' ' +
            formBuilderModel[fieldName].name +
            ' ' +
            addErrorClass()
          "
          @click="
            (e: any) => {
              inputFieldClicked(e, fieldName);
            }
          "
          @update:model-value="
            (val: any) => {
              modelUpdated(val);
            }
          "
          @change="
            (e: any) => {
              changeEvent();
            }
          "
          v-model="formBuilderModel[fieldName].formatted_value"
          autocomplete="off"
        >
          <template v-slot:append>
            <template v-if="lookup_loading_fields.hasOwnProperty(fieldName)">
              <div v-if="lookup_loading_fields[fieldName].lookup_loading">
                <q-spinner-ios color="primary" size="0.86em" />
              </div>

              <q-icon
                v-if="lookup_loading_fields[fieldName].lookup_found == true"
                flat
                dense
                name="check_circle"
                size="18px"
                class="cursor-pointer text-light-green-8"
                tabindex="0"
              >
                <q-tooltip>{{ $t('lookup_record_found') }}</q-tooltip>
              </q-icon>

              <q-icon
                v-if="lookup_loading_fields[fieldName].lookup_found == false"
                flat
                dense
                name="warning"
                size="18px"
                class="cursor-pointer text-orange"
                tabindex="0"
              >
                <q-tooltip>{{
                  interpolate(fieldName, $t('no_lookup_record_found_for_list'))
                }}</q-tooltip>
              </q-icon>
            </template>

            <q-icon
              flat
              size="18px"
              v-if="
                formBuilderModel[fieldName].hasOwnProperty('value_unmatched') &&
                formBuilderModel[fieldName].value_unmatched == true
              "
            >
              <Icon icon="mdi:not-equal-variant" width="24" height="24" />
            </q-icon>

            <q-icon
              v-if="formBuilderConfigModel[fieldName].calculator && isCalculatorIconAllowed()"
              flat
              dense
              name="calculate"
              size="18px"
              class="cursor-pointer"
              tabindex="0"
              @click="calculateValueOnCalulatorClick()"
            />

            <div
              class="cursor-pointer fuzzy-field flex items-center"
              v-if="lookup_configurations.has(fieldName)"
              @click="$event.stopPropagation();$event.preventDefault();$emit('applyFuzzySearch', formBuilderModel[fieldName]);"
            >
              <Icon icon="mdi:text-search" width="18" height="18" />
              <q-tooltip
                @before-show="getFieldsToChange(fieldName)"
                @before-hide="removeColorFromFields()"
              >
                <div class="text-bold">{{ $t('search_master_data') }}</div>
              </q-tooltip>
            </div>

            <InfoPanel :fieldName="fieldName" v-if="isExtraInfo(fieldName)" />

            <q-badge
              v-if="isFormBuilderMode && showTabIndex"
              color="orange"
              text-color="black"
              :label="formBuilderConfigModel[fieldName].tabIndex"
            />
          </template>

          <AddFieldAsLineItem
            :fieldName="fieldName"
            v-if="displayAddFieldAsLineItemMenu()"
          />
        </q-input>

        <autocomplete
          v-if="
            !isFormBuilderMode &&
            formBuilderConfigModel[fieldName].list_of_values
          "
          :input_class="fieldName + '_input'"
          :parent_id="fieldName"
          :options="
            getListOfValues(formBuilderConfigModel[fieldName].list_of_values)
          "
        />
      </div>
    </div>
  </div>

  <q-dialog
    v-model="confirmAccountingDataRest"
    persistent
    @keydown.esc="resetChange()"
  >
    <q-card>
      <q-card-section class="row items-center">
        <q-avatar icon="info" color="primary" text-color="white" />
        <span class="q-ml-sm">
          {{ $t('BY_CONFIRMING_THIS_CHANGE_YOU_WILL_LOSE_ACCOUNTING_DATA') }}
        </span>
      </q-card-section>

      <q-card-actions align="right">
        <q-btn
          flat
          :label="$t('cancel')"
          color="primary"
          v-close-popup
          @click="resetChange()"
        />
        <q-btn
          flat
          :label="$t('proceed')"
          color="primary"
          v-close-popup
          @click="removeAccountingDataAndProceed()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-dialog v-model="deleteConfirmationDlg" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('MSG_DELETE_RULE') }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          appearance="negative"
          :label="$t('delete')"
          v-close-popup
          @click="deleteRule()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';

import intUtils from 'src/utils/int';
import { defineComponent, ref } from 'vue';
import { textValidator } from 'src/validatior/index';
import { charges_table_extraction } from 'src/constants';
import { isDateField } from 'src/utils/dateCalculatedField';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import validation_mixin from 'src/validatior/validation_mixin';
import { articleNumber } from 'src/formBuilder/formBuilderConstants';
import amountConversionHelper from 'src/utils/amountConversionHelper';
import formBuilderHelper from 'src/formBuilder/utils/formBuilderHelper';
import InfoPanel from 'src/formBuilder/form_elements/components/InfoPanel.vue';
import autocomplete from 'src/formBuilder/form_elements/components/autocomplete.vue';
import AddFieldAsLineItem from 'src/formBuilder/form_elements/components/AddFieldAsLineItem.vue';
import ExtractionSourceBadge from 'src/components/ExtractionSourceBadge.vue';
import {
  dateInput,
  itemNumber,
} from 'src/formBuilder/form_elements/formatter/TextInput/index';
import { notify } from 'src/components/notifications/notify';
import {
  useSettingStore,
  useDocumentStore,
  useFormBuilderStore,
  useAmountFormatStore,
  useLookupFunctionStore,
  useFieldValuesSettingsStore,
  useDocMasterDataLookUpStore,
} from 'src/store/main';

export default defineComponent({
  name: 'TextInput',
  components: {
    
    InfoPanel,
    autocomplete,
    AddFieldAsLineItem,
    ExtractionSourceBadge,
  },
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    groupIndex: {
      type: Number,
      default: 0,
    },
    itemIndex: {
      type: Number,
      default: 0,
    },
  },
  emits: [
    'inputClicked',
    'inputValueChanges',
    'updateModel',
    'applyFuzzySearch',
    'markTableColumns',
    'itemAdded',
    'removeField',
  ],
  mixins: [displayFieldLabel,
    formBuilderHelper,
    validation_mixin,
    intUtils,
    amountConversionHelper],

  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  mounted: function () {
    this.init();
  },
  unmounted: function () {
    let inputEl = this.getInputEl();
    if (inputEl) {
      inputEl.removeEventListener('update_field_value', this.updateModel);
    }
  },
  methods: {
    async init() {
      await this.$nextTick();

      if (!this.formBuilderModel[this.fieldName]) {
        this.formBuilderModel[this.fieldName] = { formatted_value: '' };
      }

      if (this.isCalculatorIconAllowed()) {
        this.calculateValueOnCalulatorClick();
      }

      this.previousValue =
        this.formBuilderModel[this.fieldName].formatted_value;

      let inputEl = this.getInputEl();
      if (inputEl) {
        inputEl.addEventListener('update_field_value', this.updateModel);
      }
    },

    getInputEl() {
      let inputEl: HTMLInputElement | null = document!.querySelector(
        '.' + this.fieldName + '_input',
      );
      return inputEl;
    },

    updateModel(e: any) {
      try {
        if (
          this.formBuilderConfigModel[this.fieldName].list_of_values &&
          e.detail.val.includes('\u200B')
        ) {
          e.detail.val = e.detail.val.replace(/\u200B/g, '');
        }
        this.formBuilderModel[this.fieldName].formatted_value = e.detail.val;
        this.validateUpdateValue();
      } catch (err) {
        logError(err);
      }
    },

    inputFieldClicked(event: any, fieldName: string) {
      // logInfo('step 1 =========> inputFieldClicked', fieldName, event);
      event.stopPropagation();
      this.$emit('inputClicked', fieldName);
      // logInfo('Event emitted:', 'fieldName', fieldName);
    },

    // Need to add delay as formBuilderModel did not updated as soon as user manually typed in the field
    modelUpdated(val: any) {
      this.isFieldUnderEditing = true;
      setTimeout(() => {
        // this.formBuilderModel[this.fieldName].formatted_value = val;
        this.formatArtikalNummer();
        this.formBuilderModel[this.fieldName].update_timestamp = Date.now();
      }, 10);
    },

    formatArtikalNummer() {
      if (!this.isFieldArtikelNummber()) {
        return;
      }
      this.formBuilderModel[this.fieldName].formatted_value = itemNumber.format(
        this.formBuilderModel[this.fieldName].formatted_value,
      );
    },

    isFieldArtikelNummber() {
      const artikel_nummers = this.getArtikelNummerFields();
      if (artikel_nummers.includes(this.fieldName)) {
        return true;
      }
      return false;
    },

    async formatAndvalidateDate() {
      const field_type = this.getFieldType();
      if (field_type !== 'date') {
        return;
      }

      await dateInput
        .format(this.formBuilderModel[this.fieldName].formatted_value)
        .then((value: string) => {
          this.formBuilderModel[this.fieldName].formatted_value = value;
          if (value == '') {
            this.throwInputError('invalid_input_date');
          }
        });
    },

    async changeEvent() {
      const currentValue =
        this.formBuilderModel[this.fieldName].formatted_value;
      if ( currentValue !== this.previousValue && this.shouldConfirmAccountingReset(this.fieldName)) {
        this.confirmAccountingDataRest = true;
        return;
      }
      await this.proceedChangeEvent();
    },
    async proceedChangeEvent() {
      await this.formatAndvalidateDate();
      await this.validateUpdateValue();
      this.previousValue = this.formBuilderModel[this.fieldName].formatted_value;
      this.isFieldUnderEditing = false;
    },
    resetChange() {
      this.confirmAccountingDataRest = false;
      this.formBuilderModel[this.fieldName].formatted_value = this.previousValue;
      this.isFieldUnderEditing = false;
    },
    async removeAccountingDataAndProceed() {
      this.removeAccountingData();
      await this.proceedChangeEvent();
    },

    async validateUpdateValue() {
      if (this.isFormBuilderMode) {
        return;
      }
      let field_value = this.formBuilderModel[this.fieldName].formatted_value;
      this.formBuilderModel[this.fieldName].update_timestamp = Date.now();

      if (!field_value || field_value == '') {
        this.$emit('inputValueChanges', this.fieldName, 'input');
        return;
      }

      let is_valid = true;
      let input_error = '';
      this.formBuilderModel[this.fieldName].input_error = input_error;

      let fieldConfigModel = this.formBuilderConfigModel[this.fieldName];
      let fieldModel = this.formBuilderModel[this.fieldName];

      if (this.isFieldArtikelNummber()) {
        fieldConfigModel.isFieldArtikelNummber = true;
      }
      ({ is_valid, input_error } = await textValidator.init(
        fieldModel,
        fieldConfigModel,
      ));
      if (is_valid) {
        this.$emit('inputValueChanges', this.fieldName, 'input');
        return;
      }

      this.throwInputError(input_error);
    },

    throwInputError(input_error: string) {
      this.formBuilderModel[this.fieldName].input_error = input_error;

      this.$emit('inputValueChanges', this.fieldName, 'input');
    },

    fieldMask() {
      if (this.isFormBuilderMode) {
        return '';
      }

      const field_type = this.getFieldType();
      let mask = '';
      switch (field_type) {
        case 'date':
          mask = dateInput.getMask(this.getDocDateFormat());
          break;
        default:
          mask = '';
          break;
      }

      return mask;
    },

    getFieldType() {
      if (!this.formBuilderConfigModel[this.fieldName]) {
        return '';
      }

      if (!this.formBuilderConfigModel[this.fieldName].field_type) {
        return '';
      }

      return String(
        this.formBuilderConfigModel[this.fieldName].field_type.toLowerCase(),
      );
    },

    addErrorClass() {
      if (!this.hasInputError(this.fieldName)) {
        return '';
      }
      let classes = ' invalid-input ';

      if (this.formBuilderModel[this.fieldName].input_error) {
        classes +=
          ' ' + this.formBuilderModel[this.fieldName].input_error + ' ';
      }

      return classes;
    },

    deleteRuleConfirmation() {
      this.deleteConfirmationDlg = true;
    },
    deleteRule() {
      this.$emit('inputValueChanges', this.fieldName, 'delete_rule');
    },
    isCalculatorIconAllowed() {
      try {
        let rowEmpty =
          this.formBuilderConfigModel[this.fieldName].calculator != undefined &&
          this.formBuilderConfigModel[this.fieldName].calculator != null &&
          this.formBuilderConfigModel[this.fieldName].calculator == true &&
          (this.formBuilderModel[this.fieldName].formatted_value == '' ||
            this.formBuilderModel[this.fieldName].formatted_value == null);

        if (rowEmpty == false) {
          return false;
        }

        let calculator_formula =
          this.formBuilderConfigModel[this.fieldName].calculator_formula;
        var pattern = /\[(.*?)\]/g;
        let result2 = null;
        let isAnyFieldEmpty = false;

        while ((result2 = pattern.exec(calculator_formula)) !== null) {
          const field = result2[1];
          if (!this.formBuilderModel[field]) {
            return false;
          }
          const value = !this.formBuilderModel[field].value
            ? this.formBuilderModel[field].formatted_value
            : this.formBuilderModel[field].value;

          if (!value || value == '') {
            isAnyFieldEmpty = true;
            break;
          }
        }

        return isAnyFieldEmpty == true ? false : true;
      } catch (err) {
        logError(err);
        return false;
      }
    },

    async calculateValueOnCalulatorClick() {
      try {
        let field_name = this.formBuilderConfigModel[this.fieldName].field_name;
        this.removeFieldInputError(field_name);

        let calculator_formula =
          this.formBuilderConfigModel[this.fieldName].calculator_formula;
        let translated_formula = calculator_formula;
        let result2 = null;
        let isAnyFieldEmpty = false;
        var pattern = /\[(.*?)\]/g;
        const values = [];

        while ((result2 = pattern.exec(calculator_formula)) !== null) {
          const field = result2[1];

          const value = this.formBuilderModel[field].value;
          if (!value || value == '') {
            isAnyFieldEmpty = true;
            break;
          }

          values.push({
            key: this.formBuilderModel[field].formatted_value,
            value: this.formBuilderModel[field].formatted_value,
          });
        }

        if (isAnyFieldEmpty == true) {
          notify.error(
            this.$t('ERROR_CALCULATION_NOT_POSSIBLE'),
          );
          return;
        }

        // as when user types some thing in the field then the value will not be in us formate for safe side always convert them
        const formatted_values = await this.formatMultiValues(
          values,
          this.amount_format_locale,
        );

        while ((result2 = pattern.exec(calculator_formula)) !== null) {
          const field = result2[1];

          const search = '[' + field + ']';
          const amount_formatted = this.searchValueByKey(
            this.formBuilderModel[field].formatted_value,
            formatted_values,
          );
          translated_formula = translated_formula.replace(
            search,
            amount_formatted,
          );
        }

        let calculated_value = eval(translated_formula).toFixed(2);
        if (this.fieldName.startsWith('tax_rate')) {
          calculated_value = parseFloat(calculated_value).toFixed(1);
        }

        this.formBuilderModel[this.fieldName].value = calculated_value;
        this.formBuilderModel[this.fieldName].update_timestamp = Date.now();

        const formatted_value = await this.formatValue(
          calculated_value,
          'en_US',
          this.amount_format_locale,
        );
        this.formBuilderModel[this.fieldName].formatted_value = formatted_value;
        this.fieldCaluclations();

        this.$emit('inputValueChanges', this.fieldName, 'calculated');
        this.$forceUpdate();
      } catch (err) {
        logError(err);
      }
    },
    fieldCaluclations() {
      const groups = Array.isArray(this.formLayout) ? this.formLayout : [];
      for (const group of groups) {
        const rows = Array.isArray(group?.rows) ? group.rows : [];
        for (const subRow of rows) {
          if (subRow.calculation_formula) {
            // as now we have duplicating sub panels so formula needs to be recalculating
            const formula = this.prepareFormula(subRow.calculation_formula);
            this.performCalulations(
              subRow.field_name,
              formula,
              this.amount_format_locale,
              subRow.field_type,
            );
          }
        }
      }
    },

    removeFieldInputError(field_name: string) {
      if (this.formBuilderModel[field_name].hasOwnProperty('input_error')) {
        this.formBuilderModel[field_name].input_error = '';
      }
    },
    displayAddFieldAsLineItemMenu() {
      let showMenue = false;

      if (
        !this.$route.path.includes('field_validation_v1') ||
        !this.user_settings ||
        !this.user_settings[charges_table_extraction]
      ) {
        return showMenue;
      }

      if (this.formBuilderConfigModel[this.fieldName].field_type == 'AMOUNT') {
        showMenue = true;
      }

      return showMenue;
    },

    getTranslations() {
      let obj = this.formBuilderConfigModel[this.fieldName];

      if (obj.parent_field_name) {
        obj = this.formBuilderConfigModel[obj.parent_field_name];
      }

      return this.getLabelForFormBuilder(obj, '');
    },

    isFieldHidden() {
      // Check if field is hidden in Field Settings (defaultFields)
      const field = this.defaultFields.find(
        (f: any) => f.field_name === this.fieldName || f.name === this.fieldName
      );
      return field ? (field.isHidden === true) : false;
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      formLayout,
      showTabIndex,
      fieldColors,
      isFieldUnderEditing,
      defaultFields,
    } = storeToRefs(form_builder_store);
    const {
      getDocDateFormat,
      getArtikelNummerFields,
      performCalulations,
      isExtraInfo,
      hasInputError,
      showClearRuleButton,
      getFieldsToChange,
      removeColorFromFields,
    } = form_builder_store;

    const field_values_setting_store = useFieldValuesSettingsStore();
    const { getListOfValues } = field_values_setting_store;

    const doc_store = useDocumentStore();
    const { prepareFormula, removeAccountingData, shouldConfirmAccountingReset } =
      doc_store;
    const { amount_format_locale, lookup_configurations } =
      storeToRefs(doc_store);

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    const amount_format_store = useAmountFormatStore();
    const { formatValue, formatMultiValues, searchValueByKey } =
      amount_format_store;

    const lookup_function_store = useLookupFunctionStore();
    const { lookup_loading_fields } = storeToRefs(lookup_function_store);
    const { interpolate } = lookup_function_store;
    return {
      interpolate,
      lookup_loading_fields,
      lookup_configurations,
      amount_format_locale,
      getArtikelNummerFields,
      removeColorFromFields,
      getFieldsToChange,
      showClearRuleButton,
      performCalulations,
      formatMultiValues,
      searchValueByKey,
      getDocDateFormat,
      getListOfValues,
      prepareFormula,
      hasInputError,
      formatValue,
      isExtraInfo,
      user_settings,
      formLayout,
      showTabIndex,
      fieldColors,
      formBuilderModel,
      isFormBuilderMode,
      isFieldUnderEditing,
      formBuilderConfigModel,
      defaultFields,
      removeAccountingData,
      shouldConfirmAccountingReset,
      deleteConfirmationDlg: ref(false),
      confirmAccountingDataRest: ref(false),
      previousValue: ref<any>(''),
      mask: ref(''),
    };
  },
});
</script>
<style lang="scss" scoped>
.autocomplete {
  position: relative;
}
</style>
