<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useFormBuilderStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

export default defineComponent({
  name: 'auto-complete',
  render() {
    return null; // Nothing will be rendered
  },
  data() {
    return {};
  },
  props: {
    input_class: {
      type: String,
      required: true,
    },
    parent_id: {
      type: String,
      required: true,
    },
    options: {
      type: Array,
      default: [] as string[],
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { formBuilderModel } = storeToRefs(form_builder_store);

    return {
      formBuilderModel,
      suggestions_id: ref(''),
      FILTERED: ref([] as any),
      suggestionsEle: ref({} as HTMLElement),
      searchInput: ref({} as HTMLInputElement),
      parent_DIV: ref({} as HTMLElement),
      CURRENT_INDEX: ref(-1),
    };
  },
  methods: {
    handleInput(event: any) {
      // should we consider case then what about highlighting
      const userInput = event.target.value;
      const needle = userInput.toLowerCase();
      this.FILTERED = this.options.filter(
        (v: any) => v.toLowerCase().indexOf(needle) > -1,
      );
      // this.FILTERED = this.options.filter((f: any) => f.includes(userInput));
      this.suggestionsEle.innerHTML = ''; // clear out old suggestions
      this.FILTERED.forEach(this.createOption);
      if (userInput.length > 0) {
        this.openSuggestions();
      } else {
        this.closeSuggestions();
      }
    },

    highlightNext() {
      const newIndex = (this.CURRENT_INDEX + 1) % this.FILTERED.length; // loops back to the first item after the last
      this.updateIndex(newIndex);
    },

    highlightPrev() {
      const newIndex =
        (this.CURRENT_INDEX - 1 + this.FILTERED.length) % this.FILTERED.length; // loops back to the last item before first
      this.updateIndex(newIndex);
    },

    handleKeyDown(event: any) {
      // only prevent when list is opened
      const used_key_list = ['Escape', 'ArrowDown', 'ArrowUp', 'Enter'];

      if (!used_key_list.includes(event.key)) {
        return;
      }

      if (!this.suggestionsEle.hidden) {
        event.stopPropagation();
      }

      switch (event.key) {
        case 'Escape':
          this.closeSuggestions();
          break;
        case 'ArrowDown':
          this.highlightNext();
          break;
        case 'ArrowUp':
          this.highlightPrev();
          break;
        case 'Enter':
          this.selectItem(event);
      }
    },

    createOption(name: string, index: number) {
      const li = document.createElement('li');
      li.id = `option-${index}`; // we'll need this ID to track which one is highlighted
      li.className = 'suggestion-option';
      li.textContent = name;
      li.addEventListener('mouseover', () => this.updateIndex(index));
      li.addEventListener('click', this.selectItem);
      this.suggestionsEle.appendChild(li);
    },

    updateIndex(newIndex: number) {
      const prevIndex = this.CURRENT_INDEX;
      this.CURRENT_INDEX = newIndex;
      this.suggestionsEle.setAttribute(
        'aria-activedescendant',
        String(this.CURRENT_INDEX),
      ); // tells assistive-tech which li is highlighted
      const prevLi = this.suggestionsEle.querySelector(`#option-${prevIndex}`);
      const currentLi = this.suggestionsEle.querySelector(
        `#option-${this.CURRENT_INDEX}`,
      );
      if (prevLi) prevLi.classList.remove('current'); // remove prev li background
      if (currentLi) currentLi.classList.add('current'); // add bg to new li
    },

    selectItem(e: any) {
      const selected_option_value = this.FILTERED[this.CURRENT_INDEX];

      if (!selected_option_value) {
        return;
      }

      const event = new CustomEvent('update_field_value', {
        detail: {
          input_class: this.input_class,
          val: selected_option_value,
        },
      });
      this.searchInput.dispatchEvent(event);
      this.closeSuggestions();
    },

    openSuggestions() {
      // suggestions Position
      var rect = this.parent_DIV.getBoundingClientRect();
      var left = Number(rect.left + window.pageXOffset);
      var top = Number(rect.top + window.pageYOffset) + 30;

      // set style
      this.suggestionsEle.hidden = false; // show popup
      this.suggestionsEle.style.visibility = 'visible';
      this.suggestionsEle.style.left = left + 'px';
      this.suggestionsEle.style.top = top + 'px';

      // const autocomplete = document.getElementById("autocomplete");
      this.parent_DIV.setAttribute('aria-expanded', String(true)); // tell assistive tech popup is shown
      window.addEventListener('click', this.closeSuggestions); // clicking the body should close the popup
    },

    closeSuggestions() {
      this.hideSuggestions();
      this.searchInput.focus(); // focus should stay on the input
    },

    hideSuggestions() {
      this.CURRENT_INDEX = -1; // reset back to initial value
      this.suggestionsEle.hidden = true; // hide popup
      this.suggestionsEle.style.visibility = 'hidden';
      this.parent_DIV.setAttribute('aria-expanded', String(false)); // tell assistive tech popup is hidden
      window.removeEventListener('click', this.closeSuggestions); // don't need this anymore once it's closed
    },

    // setTimeout: if item is selection then parent focusout event trigger first.
    hanldFocusOut(e: any) {
      if (this.suggestionsEle.hidden) {
        return;
      }
      setTimeout(() => {
        this.hideSuggestions();
      }, 1000);
    },

    async init() {
      await this.$nextTick();
      // unique input_class & parent_id
      let searchInput: HTMLInputElement | null = document!.querySelector(
        '.' + this.input_class,
      );
      if (!searchInput) {
        logError('search Input not found', this.input_class);
        return;
      }

      const ul = document.createElement('ul');
      ul.setAttribute('id', this.suggestions_id);
      ul.setAttribute('class', 'sugg');
      document.body.appendChild(ul);

      const autocomplete = document.getElementById(
        this.parent_id,
      ) as HTMLElement;
      if (!autocomplete) {
        logError('parent element not found', this.parent_id);
        return;
      }

      this.parent_DIV = autocomplete;
      this.searchInput = searchInput;
      this.suggestionsEle = ul;

      this.searchInput.addEventListener('blur', this.hanldFocusOut);
      this.searchInput.addEventListener('focusout', this.hanldFocusOut);

      this.searchInput.addEventListener('input', this.handleInput);
      this.parent_DIV.addEventListener('keydown', this.handleKeyDown);

      window.addEventListener('scroll', this.hideSuggestions, true);
    },
  },
  mounted: function () {
    this.suggestions_id = this.input_class + '_suggestions';
    this.init();
  },
  unmounted: function () {
    window.removeEventListener('scroll', this.hideSuggestions, true);

    let searchInput: HTMLInputElement | null = document!.querySelector(
      '.' + this.input_class,
    );
    if (searchInput) {
      searchInput.removeEventListener('input', this.handleInput);
      this.searchInput.removeEventListener('blur', this.hanldFocusOut);
      this.searchInput.removeEventListener('focusout', this.hanldFocusOut);
    }

    const autocomplete = document.getElementById(this.parent_id) as HTMLElement;
    if (autocomplete) {
      autocomplete.removeEventListener('keydown', this.handleKeyDown);
    }
  },
});
</script>
