  list-style: none;
  padding: 0;
  position: fixed !important;
  display: inline-block;
  max-width: 95vw;
  background: var(--fb-bg-primary);
  border: 1px solid var(--fb-border-light);
  border-radius: 4px;
  overflow-y: auto;
  overflow-x: hidden;
  outline: 0;
  max-height: 65vh;
  z-index: 6000;
}
</style>
