<template>
  <div class="full-width full-height cursor-pointer">
    <span @click="$emit('inputClicked', fieldName)">
      {{
        getLabelForFormBuilder(
          formBuilderConfigModel[fieldName],
          '',
        )
      }}
    </span>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useFormBuilderStore } from 'src/store/main';
import displayFieldLabel from 'src/utils/displayFieldLabel';

export default defineComponent({
  name: 'TextInput',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['updateModel', 'inputClicked'],
  mixins: [displayFieldLabel],

  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  methods: {
    getLowerConfidence(field: any): any {
      if (this.isFormBuilderMode) {
        return null;
      }
      return this.getLowerConfidence(field);
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { formBuilderConfigModel, isFormBuilderMode } =
      storeToRefs(form_builder_store);
    return {
      isFormBuilderMode,
      formBuilderConfigModel,
    };
  },
});
</script>
