<template>
  <q-menu touch-position context-menu>
    <q-list dense style="min-width: 100px">
      <q-item clickable v-close-popup @click="showAddLineItemDialog()">
        <q-item-section>Select as line Item</q-item-section>
      </q-item>
      <q-separator />
      <q-item clickable v-close-popup>
        <q-item-section>{{ $t('close') }}</q-item-section>
      </q-item>
    </q-list>
  </q-menu>

  <q-dialog
    v-model="addLineItemDialog"
    persistent
    transition-show="scale"
    transition-hide="scale"
  >
    <q-card style="width: 600px">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">{{ $t('add_line_row') }}</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section>
        <div class="row">
          <div class="col-sm-12 col-md-12 col-lg-12 q-mt-sm">
            <q-input
              dense
              :label="$t('amount')"
              v-model="addLineModel['amount']"
              outlined
              class="full-width"
            />
          </div>

          <div class="col-sm-12 col-md-12 col-lg-12 q-mt-sm">
            <q-select
              dense
              outlined
              v-model="addLineModel['position']"
              :options="positionList"
              :label="$t('position')"
              emit-value
              map-options
            />
          </div>

          <div class="col-sm-12 col-md-12 col-lg-12 q-mt-sm">
            <q-input
              dense
              :label="$t('description')"
              v-model="addLineModel['description']"
              outlined
              class="full-width"
            />
          </div>

          <div class="col-sm-12 col-md-12 col-lg-12 q-mt-sm">
            <q-select
              dense
              outlined
              v-model="addLineModel['costing_element']"
              :options="costingElementList"
              :label="$t('costing_element')"
              emit-value
              map-options
            />
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />

        <f-btn
          class="q-mr-sm"
          data-cy="setvatfield"
          :label="$t('proceed')"
          @click="selectAsLineItem()"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { notify } from 'src/components/notifications/notify';
import {
  useFormBuilderStore,
  useDocumentStore,
  useMasterDataLookupStore,
} from 'src/store/main';

export default defineComponent({
    data() {
    return {
      addLineItemDialog: ref(false),
      addLineModel: ref({} as any),
    };
  },
  props: {
    fieldName: {
      type: String,
      required: true,
    },
  },
  mounted: function () {
    this.init();
  },
  methods: {
    async init() {
      this.initPositionList();
      this.costingElementList = await this.getCostingElementList(['1', '3']);
    },
    initPositionList() {
      this.positionList = [];
      if (!this.record.tables || !this.record.tables[0]) {
        return;
      }
      this.tableObj = this.record.tables[0];

      for (const [rowKey, tableRow] of Object.entries(this.tableObj.rows)) {
        const row = tableRow as any;

        if (row.hasOwnProperty('parent_id')) {
          continue;
        }
        for (const [key, tableColumn] of Object.entries(row.columns)) {
          const column = tableColumn as any;
          if (column.name === 'POSITION') {
            this.positionList.push({
              label: column.formatted_value,
              value: rowKey,
            });
          }
        }
      }
    },
    showAddLineItemDialog() {
      if (!this.formBuilderModel[this.fieldName].formatted_value) {
        notify.error(
          this.$t('CAN_NOT_PROCEED_ON_EMPTY_FIELD'),
        );
        return;
      }

      this.addLineItemDialog = true;
      this.initLineModel();
    },
    initLineModel() {
      this.addLineModel = {
        amount: this.formBuilderModel[this.fieldName].formatted_value,
        position: '',
        description: '',
        costing_element: '',
      };
    },
    selectAsLineItem() {
      if (!this.formBuilderModel[this.fieldName].formatted_value) {
        notify.error(
          this.$t('CAN_NOT_PROCEED_ON_EMPTY_FIELD'),
        );
        return;
      }

      for (let key of Object.keys(this.addLineModel)) {
        if (!this.addLineModel[key]) {
          notify.error(
            this.$t('FIELD_IS_MANDATORY', {
              field: this.$t(key),
            }),
          );
          break;
        }
      }

      let emptyModel = {} as any;

      this.record.fields.forEach((fieldData: any, index: any) => {
        if (fieldData.name === this.fieldName) {
          fieldData.content = '';
          fieldData.formatted_value = '';
          fieldData.value = '';
          fieldData.extraction_method = '';
          fieldData.is_validated = true;
          fieldData.is_valid = true;
          fieldData.coords = [];
          delete fieldData.page;

          emptyModel = fieldData;
        }
      });

      const event = new CustomEvent('add_new_row', {
        detail: {
          addLineModel: this.addLineModel,
          field: this.formBuilderModel[this.fieldName],
        },
      });
      document.dispatchEvent(event);

      this.formBuilderModel[this.fieldName] = [];
      this.formBuilderModel[this.fieldName] = emptyModel;

      this.addLineItemDialog = false;
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      formLayout,
    } = storeToRefs(form_builder_store);

    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);

    const master_data_lookup = useMasterDataLookupStore();
    const { getCostingElementList } = master_data_lookup;

    return {
      record,
      formLayout,
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      costingElementList: [] as any,
      positionList: [] as any,
      tableObj: [] as any,

      getCostingElementList,
    };
  },
});
</script>
